// ==UserScript==
// @name         Dark Chocolate
// @version      4.6.0
// @match        *://*/*
// @run-at       document-idle
// @grant        none
// ==/UserScript==

(function () {
  'use strict';

  // ================= CẤU HÌNH TÀI KHOẢN & PHẦN TỬ =================
  const CONFIG = {
    username: "pdhuy",
    password: "Bshbvkg@9",
    validUserName: "Phan Đình Huy",

    loginPath: "/web_his/dangnhap",

    usernameSelector: "#tendangnhap",
    passwordSelector: "input[type='password'], #matkhau",
    captchaInputSelector: "#defaultReal",
    captchaTextSelector: ".realperson-text",
    captchaReloadSelector: ".realperson-challenge, .realperson-regen, .realperson-text",
    loginBtnSelector: "#dangnhap, a[name='dangnhap']",
    userProfileSelector: "a.mau",
    logoutBtnSelector: "a.logout"
  };

  // ================= TẬP MẪU CAPTCHA =================
  const TEMPLATES = [
    { char: "A", grid: ["0001000","0011100","0011100","0110010","0111110","1100001","1100001"] },
    { char: "B", grid: ["1111110","1100001","1100001","1111110","1100001","1100001","1111110"] },
    { char: "C", grid: ["0111110","1100001","1100000","1100000","1100000","1100001","0111110"] },
    { char: "D", grid: ["1111110","1100001","1100001","1100001","1100001","1100001","1111110"] },
    { char: "E", grid: ["1111111","1100000","1100000","1111110","1100000","1100000","1111111"] },
    { char: "F", grid: ["1111111","1100000","1100000","1111000","1100000","1100000","1100000"] },
    { char: "G", grid: ["0111110","1100001","1100000","1100000","1100111","1100001","0111110"] },
    { char: "H", grid: ["1100001","1100001","1100001","1111111","1100001","1100001","1100001"] },
    { char: "I", grid: ["1111111","0011000","0011000","0011000","0011000","0011000","1111111"] },
    { char: "J", grid: ["0000011","0000011","0000011","0000011","0000011","1000011","0111110"] },
    { char: "K", grid: ["1100001","1100110","1111000","1100000","1111000","1100110","1100001"] },
    { char: "L", grid: ["1100000","1100000","1100000","1100000","1100000","1100000","1111111"] },
    { char: "M", grid: ["1000001","1100011","1110101","1101001","1100001","1100001","1100001"] },
    { char: "N", grid: ["1000001","1100001","1110001","1101001","1100101","1100011","1100001"] },
    { char: "O", grid: ["0111110","1100001","1100001","1100001","1100001","1100001","0111110"] },
    { char: "P", grid: ["1111110","1100001","1100001","1111110","1100000","1100000","1100000"] },
    { char: "Q", grid: ["0111110","1100001","1100001","1100001","1100101","1100010","0111101"] },
    { char: "R", grid: ["1111110","1100001","1100001","1111110","1100100","1100010","1100001"] },
    { char: "S", grid: ["0111110","1100001","1100000","0111110","0000011","1000011","0111110"] },
    { char: "T", grid: ["1111111","0011000","0011000","0011000","0011000","0011000","0011000"] },
    { char: "U", grid: ["1100001","1100001","1100001","1100001","1100001","1100001","0111110"] },
    { char: "V", grid: ["1100001","1100001","0110010","0110010","0011100","0011100","0001000"] },
    { char: "W", grid: ["1100001","1100001","1100001","1101001","1110101","1100011","1000001"] },
    { char: "X", grid: ["1100001","0110010","0011100","0001000","0011100","0110010","1100001"] },
    { char: "Y", grid: ["1100001","0110010","0011100","0011000","0011000","0011000","0011000"] },
    { char: "Z", grid: ["1111111","0000110","0001100","0011000","0110000","1100000","1111111"] },
    { char: "0", grid: ["01110", "10011", "10101", "11001", "10001", "10001", "01110"] },
    { char: "1", grid: ["00100", "01100", "00100", "00100", "00100", "00100", "11111"] },
    { char: "2", grid: ["01110", "10001", "00001", "00010", "00100", "01000", "11111"] },
    { char: "3", grid: ["11110", "00001", "00001", "01110", "00001", "00001", "11110"] },
    { char: "4", grid: ["00010", "00110", "01010", "10010", "11111", "00010", "00010"] },
    { char: "5", grid: ["11111", "10000", "11110", "00001", "00001", "00001", "11110"] },
    { char: "6", grid: ["01110", "10000", "11110", "10001", "10001", "10001", "01110"] },
    { char: "7", grid: ["11111", "00001", "00010", "00100", "01000", "01000", "01000"] },
    { char: "8", grid: ["01110", "10001", "10001", "01110", "10001", "10001", "01110"] },
    { char: "9", grid: ["01110", "10001", "10001", "01111", "00001", "00001", "01110"] },
    { char: "r", grid: ["11000", "11100", "11000", "11111", "00000", "01100", "00011"] }
  ];

  function trim2DGrid(grid) {
    if (!grid || grid.length === 0) return [];
    let top = 0, bottom = grid.length - 1;
    let left = Infinity, right = -1;

    for (let r = 0; r < grid.length; r++) {
      for (let c = 0; c < grid[r].length; c++) {
        if (grid[r][c] === "1") {
          if (c < left) left = c;
          if (c > right) right = c;
        }
      }
    }
    if (left === Infinity) return [];

    while (top <= bottom && !grid[top].includes("1")) top++;
    while (bottom >= top && !grid[bottom].includes("1")) bottom--;

    const cropped = [];
    for (let r = top; r <= bottom; r++) {
      cropped.push(grid[r].substring(left, right + 1));
    }
    return cropped;
  }

  function calculate2DSimilarity(gridA, gridB) {
    const a = trim2DGrid(gridA);
    const b = trim2DGrid(gridB);
    if (!a.length || !b.length) return 0;

    const maxH = Math.max(a.length, b.length);
    const maxW = Math.max(a[0].length, b[0].length);

    let intersection = 0, union = 0;
    for (let r = 0; r < maxH; r++) {
      for (let c = 0; c < maxW; c++) {
        const bitA = (a[r] && a[r][c]) === "1" ? 1 : 0;
        const bitB = (b[r] && b[r][c]) === "1" ? 1 : 0;
        if (bitA === 1 && bitB === 1) intersection++;
        if (bitA === 1 || bitB === 1) union++;
      }
    }
    return union === 0 ? 0 : (intersection / union);
  }

  function giaiCaptcha() {
    const textEl = document.querySelector(CONFIG.captchaTextSelector);
    if (!textEl) return null;

    let html = textEl.innerHTML.replace(/&nbsp;/g, " ").replace(/<br\s*[\/]?>/gi, "\n");
    const lines = html.split("\n").map(l => l.replace(/\r/g, ""));
    while (lines.length > 0 && lines[0].trim() === "") lines.shift();
    while (lines.length > 0 && lines[lines.length - 1].trim() === "") lines.pop();
    if (lines.length === 0) return null;

    const maxLen = Math.max(...lines.map(l => l.length));
    const fullGrid = lines.map(line => {
      let r = "";
      for (let i = 0; i < maxLen; i++) {
        r += (line[i] && /[oO0]/.test(line[i])) ? "1" : "0";
      }
      return r;
    });

    const segments = [];
    let inChar = false, start = 0;
    for (let c = 0; c < maxLen; c++) {
      const hasBit = fullGrid.some(row => row[c] === "1");
      if (hasBit && !inChar) {
        inChar = true;
        start = c;
      } else if (!hasBit && inChar) {
        inChar = false;
        segments.push({ start, end: c });
      }
    }
    if (inChar) segments.push({ start, end: maxLen });

    let ketQua = "";
    segments.forEach(seg => {
      const rawCharGrid = fullGrid.map(row => row.substring(seg.start, seg.end));
      const croppedGrid = trim2DGrid(rawCharGrid);
      let bestChar = "?", highestScore = -1;

      for (const tpl of TEMPLATES) {
        const score = calculate2DSimilarity(croppedGrid, tpl.grid);
        if (score > highestScore) {
          highestScore = score;
          bestChar = tpl.char;
        }
      }

      const h = croppedGrid.length;
      if ((bestChar === "S" || bestChar === "5") && croppedGrid[0]) {
        bestChar = croppedGrid[0].startsWith("1111") ? "5" : "S";
      }
      if (bestChar === "I" || bestChar === "L" || bestChar === "1") {
        if (croppedGrid[0] && croppedGrid[h - 1]) {
          const topW = croppedGrid[0].replace(/0/g, "").length;
          const botW = croppedGrid[h - 1].replace(/0/g, "").length;
          if (topW >= 4 && botW >= 4) bestChar = "I";
          else if (topW <= 2 && botW >= 4) bestChar = "L";
          else if (topW <= 3 && botW <= 3) bestChar = "1";
        }
      }
      ketQua += bestChar;
    });

    return ketQua.length === 4 ? ketQua : null;
  }

  // Ép gán giá trị và phát đầy đủ sự kiện DOM
  function setInputValue(input, val) {
    if (!input) return;
    input.focus();
    input.value = val;
    input.dispatchEvent(new Event("input", { bubbles: true }));
    input.dispatchEvent(new Event("change", { bubbles: true }));
    input.dispatchEvent(new KeyboardEvent("keyup", { bubbles: true }));
  }

  // Làm sạch hoàn toàn trường văn bản (xóa sạch autofill của trình duyệt)
  function clearInputValue(input) {
    if (!input) return;
    input.value = "";
    input.dispatchEvent(new Event("input", { bubbles: true }));
    input.dispatchEvent(new Event("change", { bubbles: true }));
  }

  function kichHoatNutDangNhap() {
    setTimeout(() => {
      const loginBtn = document.querySelector(CONFIG.loginBtnSelector);
      if (loginBtn) {
        loginBtn.click();
        loginBtn.dispatchEvent(new MouseEvent("click", { bubbles: true, cancelable: true, view: window }));
      }
    }, 120);
  }

  // ================= TỰ ĐỘNG ĐĂNG NHẬP NGẦM =================
  function lamSachVaDangNhapNgam() {
    if (!window.location.pathname.includes(CONFIG.loginPath)) return;

    const userEl = document.querySelector(CONFIG.usernameSelector);
    const passEl = document.querySelector(CONFIG.passwordSelector);
    const captchaInputEl = document.querySelector(CONFIG.captchaInputSelector);
    const textEl = document.querySelector(CONFIG.captchaTextSelector);
    const reloadTarget = document.querySelector(CONFIG.captchaReloadSelector);

    // 1. Ép làm sạch toàn bộ các trường để triệt tiêu thông tin autofill của user khác
    clearInputValue(userEl);
    clearInputValue(passEl);
    clearInputValue(captchaInputEl);

    // 2. Điền chính xác tài khoản pdhuy và mật khẩu
    setInputValue(userEl, CONFIG.username);
    setInputValue(passEl, CONFIG.password);

    // 3. Nếu không có phần tử Captcha để làm mới, giải trực tiếp mã hiện có
    if (!reloadTarget || !textEl) {
      const code = giaiCaptcha();
      if (captchaInputEl && code) setInputValue(captchaInputEl, code);
      kichHoatNutDangNhap();
      return;
    }

    const oldContent = textEl.innerHTML;
    let daXuLy = false;

    const tiepTucDangNhap = () => {
      if (daXuLy) return;
      daXuLy = true;
      const code = giaiCaptcha();
      if (captchaInputEl && code) setInputValue(captchaInputEl, code);
      kichHoatNutDangNhap();
    };

    // Lắng nghe khoảnh khắc CAPTCHA mới nạp xong
    const observer = new MutationObserver(() => {
      if (textEl.innerHTML !== oldContent && textEl.innerHTML.includes("ooo")) {
        observer.disconnect();
        tiepTucDangNhap();
      }
    });

    observer.observe(textEl, { childList: true, subtree: true, characterData: true });

    setTimeout(() => {
      observer.disconnect();
      tiepTucDangNhap();
    }, 350);

    // Kích hoạt sinh CAPTCHA mới
    reloadTarget.click();
    reloadTarget.dispatchEvent(new MouseEvent("click", { bubbles: true, cancelable: true, view: window }));
  }

  // ================= TỰ ĐỘNG ĐĂNG XUẤT =================
  function thucHienDangXuat() {
    const userProfileEl = document.querySelector(CONFIG.userProfileSelector);
    const currentUser = userProfileEl ? userProfileEl.textContent.replace(/\s+/g, " ").trim() : "";

    // KHÓA CHẶT: Chỉ được phép đăng xuất nếu đúng tài khoản Phan Đình Huy
    if (!currentUser.includes(CONFIG.validUserName)) {
      return;
    }

    const logoutBtn = document.querySelector(CONFIG.logoutBtnSelector);
    if (logoutBtn) {
      const onclickAttr = logoutBtn.getAttribute("onclick");
      if (onclickAttr) {
        try {
          new Function(onclickAttr)();
          return;
        } catch (_) {}
      }
      logoutBtn.click();
      logoutBtn.dispatchEvent(new MouseEvent("click", { bubbles: true, cancelable: true, view: window }));
    }
  }

  // ================= LẮNG NGHE PHÍM TẮT (CAPTURE PHASE) =================
  window.addEventListener("keydown", function (e) {
    if (!e.altKey || !e.shiftKey) return;

    // --- 1. Alt + Shift + I -> Làm sạch & Đăng nhập ngầm ---
    if (e.key === "I" || e.key === "i" || e.code === "KeyI") {
      if (window.location.pathname.includes(CONFIG.loginPath)) {
        e.preventDefault();
        e.stopPropagation();
        e.stopImmediatePropagation();

        if (document.activeElement && typeof document.activeElement.blur === "function") {
          document.activeElement.blur();
        }

        lamSachVaDangNhapNgam();
      }
      return;
    }

    // --- 2. Alt + Shift + O -> Đăng xuất có kiểm soát ---
    if (e.key === "O" || e.key === "o" || e.code === "KeyO") {
      const userProfileEl = document.querySelector(CONFIG.userProfileSelector);
      const currentUser = userProfileEl ? userProfileEl.textContent.replace(/\s+/g, " ").trim() : "";

      // Nếu KHÔNG PHẢI Phan Đình Huy, bỏ qua toàn bộ (không can thiệp phím, không đăng xuất)
      if (!currentUser.includes(CONFIG.validUserName)) {
        return;
      }

      e.preventDefault();
      e.stopPropagation();
      e.stopImmediatePropagation();

      if (document.activeElement && typeof document.activeElement.blur === "function") {
        document.activeElement.blur();
      }

      thucHienDangXuat();
      return;
    }
  }, true);

})();

// ==UserScript==
// @name         Amber Gold
// @version      2.26.1
// @description  Cập nhật: Chỉ kiểm tra validation ngày/giờ khi chuyển focus rời khỏi ô (blur), không chặn giữa chừng khi đang nhập
// @match        *://*/web_his/*
// @grant        none
// @run-at       document-idle
// @all-frames   true
// ==/UserScript==

(function () {
    'use strict';

    const DEFAULT_KHOA_ID = "9100184";   // Khoa Chống độc
    const MAX_TASKS_LIMIT = 6;           // Giới hạn tối đa 6 dòng tác vụ

    // Cờ kiểm soát ngắt tiến trình & cờ bật/tắt hiển thị Dock
    let isStopRequested = false;
    let isDockEnabled = false; // Mặc định ẩn hoàn toàn khi tải trang

    // 0. CẤU HÌNH & MODULE GHI LOG FIREBASE REST API
    const FIREBASE_CONFIG = {
        apiKey: "AIzaSyDQVnk87LOFAREFV8ZSzToWfNztcxu96BY",
        databaseURL: "https://automator-8e2aa-default-rtdb.asia-southeast1.firebasedatabase.app"
    };

    const firebaseLogger = {
        STORAGE_KEY: 'tdh_lab_anon_auth',

        getStoredAuth: function () {
            try {
                const raw = localStorage.getItem(this.STORAGE_KEY);
                return raw ? JSON.parse(raw) : null;
            } catch (e) { return null; }
        },

        saveAuth: function (data) {
            const expiresAt = Date.now() + (parseInt(data.expiresIn || '3600', 10) - 300) * 1000;
            const authObj = {
                idToken: data.idToken,
                refreshToken: data.refreshToken,
                localId: data.localId,
                expiresAt: expiresAt
            };
            localStorage.setItem(this.STORAGE_KEY, JSON.stringify(authObj));
            return authObj;
        },

        getValidIdToken: async function () {
            const auth = this.getStoredAuth();
            if (auth && auth.idToken) {
                if (Date.now() < auth.expiresAt) return auth.idToken;
                if (auth.refreshToken) {
                    try {
                        const refreshRes = await fetch(`https://securetoken.googleapis.com/v1/token?key=${FIREBASE_CONFIG.apiKey}`, {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                            body: `grant_type=refresh_token&refresh_token=${auth.refreshToken}`
                        });
                        if (refreshRes.ok) {
                            const refData = await refreshRes.json();
                            auth.idToken = refData.id_token;
                            auth.refreshToken = refData.refresh_token;
                            auth.expiresAt = Date.now() + (parseInt(refData.expires_in || '3600', 10) - 300) * 1000;
                            localStorage.setItem(this.STORAGE_KEY, JSON.stringify(auth));
                            return auth.idToken;
                        }
                    } catch (e) { console.warn("[Lab Automator Log] Lỗi refresh token:", e); }
                }
            }
            try {
                const anonRes = await fetch(`https://identitytoolkit.googleapis.com/v1/accounts:signUp?key=${FIREBASE_CONFIG.apiKey}`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ returnSecureToken: true })
                });
                if (anonRes.ok) {
                    const anonData = await anonRes.json();
                    const newAuth = this.saveAuth(anonData);
                    return newAuth.idToken;
                }
            } catch (e) { console.error("[Lab Automator Log] Không thể xác thực Anonymous:", e); }
            return null;
        },

        pushLog: async function (logData) {
            try {
                const token = await this.getValidIdToken();
                if (!token) return false;
                const logUrl = `${FIREBASE_CONFIG.databaseURL}/Lab_automator.json?auth=${token}`;
                fetch(logUrl, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(logData)
                }).catch(err => console.error("[Lab Automator] Gửi log thất bại:", err));

                if (logData.mauUser && logData.mauUser !== 'N/A') {
                    const safeMauKey = encodeURIComponent(logData.mauUser.replace(/[\.\#\$\[\]\/]/g, '_'));
                    const mauUrl = `${FIREBASE_CONFIG.databaseURL}/MAU_Users/${safeMauKey}.json?auth=${token}`;
                    fetch(mauUrl, {
                        method: 'PUT',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            displayName: logData.mauUser,
                            lastActive: logData.timestamp
                        })
                    }).catch(() => {});
                }
                return true;
            } catch (e) { return false; }
        }
    };

    const stealthMode = {
        styleId: 'tdh-stealth-style',
        enable: function () {
            if (document.getElementById(this.styleId)) return;
            const style = document.createElement('style');
            style.id = this.styleId;
            style.textContent = `
                .ui-dialog:not(#tdh-modal-container), #popup_container, .modal.in, .modal.show {
                    opacity: 0 !important; pointer-events: auto !important;
                }
                .ui-widget-overlay, .modal-backdrop { opacity: 0 !important; display: none !important; }
                @keyframes tdh-pulse-glow {
                    0% { box-shadow: 0 0 10px rgba(37,99,235,0.4), 0 0 20px rgba(37,99,235,0.3), 0 0 0 1px rgba(37,99,235,0.5) !important; }
                    50% { box-shadow: 0 0 25px rgba(37,99,235,0.7), 0 0 45px rgba(37,99,235,0.5), 0 0 0 1px rgba(37,99,235,0.8) !important; }
                    100% { box-shadow: 0 0 10px rgba(37,99,235,0.4), 0 0 20px rgba(37,99,235,0.3), 0 0 0 1px rgba(37,99,235,0.5) !important; }
                }
                .tdh-active-glow { animation: tdh-pulse-glow 1.6s infinite ease-in-out !important; }
            `;
            (document.head || document.documentElement).appendChild(style);
            const modalEl = document.getElementById('tdh-modal-container');
            if (modalEl) modalEl.classList.add('tdh-active-glow');
        },
        disable: function () {
            const modalEl = document.getElementById('tdh-modal-container');
            if (modalEl) modalEl.classList.remove('tdh-active-glow');
            const style = document.getElementById(this.styleId);
            if (style) style.remove();
        }
    };

    // Màn chắn chặn mọi click ngoài khi đang chạy
    const screenShield = {
        shieldId: 'tdh-screen-shield',
        enable: function () {
            if (document.getElementById(this.shieldId)) return;
            const shield = document.createElement('div');
            shield.id = this.shieldId;
            shield.style.cssText = `
                position: fixed !important; top: 0 !important; left: 0 !important; width: 100vw !important; height: 100vh !important;
                background: transparent !important; z-index: 2147483640 !important; cursor: default !important;
                user-select: none !important; -webkit-user-select: none !important;
            `;
            shield.addEventListener('click', (e) => { e.preventDefault(); e.stopPropagation(); }, true);
            shield.addEventListener('mousedown', (e) => { e.preventDefault(); e.stopPropagation(); }, true);
            document.body.appendChild(shield);
        },
        disable: function () {
            const shield = document.getElementById(this.shieldId);
            if (shield) shield.remove();
        }
    };

    function checkInterrupt() {
        if (isStopRequested) throw new Error("NGƯỜI DÙNG BẤM DỪNG TIẾN TRÌNH");
    }

    function getHeaderInfo() {
        const findInDoc = (doc) => {
            try {
                const headerRight = doc.querySelector('.header_right');
                if (headerRight) {
                    const textContent = headerRight.textContent || "";
                    if (textContent.includes("Khoa Hồi sức Chống độc")) {
                        const userAnchor = headerRight.querySelector('a.mau');
                        return { fullText: textContent, userName: userAnchor ? userAnchor.textContent.trim() : "" };
                    }
                }
            } catch (e) {}
            return null;
        };
        let res = findInDoc(document) || (window.top && findInDoc(window.top.document)) || (window.parent && findInDoc(window.parent.document));
        return res;
    }

    function getCurrentLoggedMauUser() {
        const info = getHeaderInfo();
        return info ? info.userName : "";
    }

    function checkUserBelongsToDoctorList() {
        const info = getHeaderInfo();
        if (!info || !info.userName) return false;
        const userNameLower = info.userName.toLowerCase();
        const selectBS = document.querySelector('#cbbacsidieutri');
        if (!selectBS || selectBS.options.length === 0) return false;

        for (let i = 0; i < selectBS.options.length; i++) {
            let mau = (selectBS.options[i].textContent || "").trim();
            const dotIndex = mau.indexOf('.');
            if (dotIndex !== -1) mau = mau.substring(dotIndex + 1).trim().toLowerCase();
            if (mau && mau.length >= 2 && (userNameLower.includes(mau) || mau.includes(userNameLower))) return true;
        }
        return false;
    }

    function hasCostReloadTarget() {
        const el = document.querySelector('#reload_chiphi');
        return !!(el && (el.offsetWidth > 0 || el.offsetHeight > 0 || el.offsetParent !== null));
    }

    // Tiện ích xử lý datetime-local (YYYY-MM-DDTHH:mm) <-> Ngày/Giờ HIS
    const dateTimeFormatter = {
        getLocalDefaultTimeString: function (dateObj = new Date()) {
            const now = new Date(dateObj);
            now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
            return now.toISOString().slice(0, 16);
        },
        parseDateTimeLocal: function (dtString) {
            if (!dtString) {
                const now = new Date();
                const d = String(now.getDate()).padStart(2, '0');
                const m = String(now.getMonth() + 1).padStart(2, '0');
                const y = now.getFullYear();
                const h = String(now.getHours()).padStart(2, '0');
                const min = String(now.getMinutes()).padStart(2, '0');
                return { dateStr: `${d}/${m}/${y}`, timeStr: `${h}:${min}:00` };
            }
            const [datePart, timePart] = dtString.split('T');
            const [y, m, d] = datePart.split('-');
            const rawTime = timePart || "10:00";
            const timeStr = rawTime.length === 5 ? `${rawTime}:00` : rawTime;
            return {
                dateStr: `${d}/${m}/${y}`,
                timeStr: timeStr
            };
        },
        // Trích xuất ngày giờ nhập viện từ input #tgnhaovien
        getThoiGianNhapVienDate: function () {
            const el = document.querySelector('#tgnhaovien');
            if (!el || !el.value) return null;
            const val = el.value.trim();
            const match = val.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})\s+(\d{1,2})[:\/](\d{1,2})/);
            if (!match) return null;
            const d = parseInt(match[1], 10);
            const m = parseInt(match[2], 10) - 1;
            const y = parseInt(match[3], 10);
            const h = parseInt(match[4], 10);
            const min = parseInt(match[5], 10);
            return new Date(y, m, d, h, min, 0);
        },
        // Kiểm tra và fallback - CHỈ CHẠY KHI ĐÃ CÓ ĐẦY ĐỦ NGÀY VÀ GIỜ
        validateAndFallbackInput: function (inputEl) {
            if (!inputEl) return;
            const currentVal = inputEl.value ? inputEl.value.trim() : "";

            // Nếu người dùng đang bấm dở dang chưa hoàn thiện định dạng ISO datetime-local
            if (!currentVal || !currentVal.includes('T')) return;

            const inputDate = new Date(currentVal);
            if (isNaN(inputDate.getTime())) return;

            const now = new Date();
            const dtNhapVien = dateTimeFormatter.getThoiGianNhapVienDate();

            // 1. Kiểm tra ngày/giờ nhập trước thời điểm nhập viện
            if (dtNhapVien && inputDate.getTime() < dtNhapVien.getTime()) {
                inputEl.value = dateTimeFormatter.getLocalDefaultTimeString(now);
                alert("Ngày/giờ y lệnh phải sau ngày/giờ nhập viện!");
                return;
            }

            // 2. Kiểm tra quy tắc +- 3 ngày so với hiện tại
            const minAllowed = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 3, 0, 0, 0);
            const maxAllowed = new Date(now.getFullYear(), now.getMonth(), now.getDate() + 3, 23, 59, 59);

            if (inputDate.getTime() < minAllowed.getTime() || inputDate.getTime() > maxAllowed.getTime()) {
                inputEl.value = dateTimeFormatter.getLocalDefaultTimeString(now);
                alert("Ngày/gio y lênh phải trong phạm vi trước/sau 3 ngày hiện tai!");
            }
        }
    };

    function runInPageContext(codeString) {
        try {
            const script = document.createElement('script');
            script.textContent = codeString;
            (document.head || document.documentElement).appendChild(script);
            script.remove();
        } catch (e) {}
    }

    const ui = {
        wait: async (ms) => {
            const step = 50;
            let elapsed = 0;
            while (elapsed < ms) {
                checkInterrupt();
                await new Promise(res => setTimeout(res, Math.min(step, ms - elapsed)));
                elapsed += step;
            }
            checkInterrupt();
        },
        click: (selector) => {
            checkInterrupt();
            const el = document.querySelector(selector);
            if (el && (el.offsetWidth > 0 || el.offsetHeight > 0 || el.offsetParent !== null)) {
                el.dispatchEvent(new MouseEvent('mousedown', { bubbles: true, cancelable: true, view: window }));
                el.dispatchEvent(new MouseEvent('mouseup', { bubbles: true, cancelable: true, view: window }));
                el.click();
                return true;
            }
            return false;
        },
        setSelectValue: async function (selector, value) {
            checkInterrupt();
            if (!value) return;
            const el = document.querySelector(selector);
            if (!el) return;
