            el.value = value;
            el.dispatchEvent(new Event('input', { bubbles: true }));
            el.dispatchEvent(new Event('change', { bubbles: true }));
            const safeSelector = selector.replace(/'/g, "\\'");
            const safeValue = value.replace(/'/g, "\\'");
            runInPageContext(`try { var $el = window.jQuery ? window.jQuery('${safeSelector}') : null; if ($el && $el.length) { $el.prop('disabled', false).val('${safeValue}').trigger('change'); } } catch(e){}`);
