        },
        setInputValueDirect: async function (selector, value) {
            checkInterrupt();
            const el = document.querySelector(selector);
            if (!el) return;
            if (el.disabled) el.disabled = false;
            if (el.readOnly) el.readOnly = false;
            const oldValue = el.value;
            const isValueChanged = oldValue !== value;
            el.value = value;
            const safeSelector = selector.replace(/'/g, "\\'");
            const safeValue = value.replace(/'/g, "\\'");
            runInPageContext(`try { var $el = window.jQuery ? window.jQuery('${safeSelector}') : null; if ($el && $el.length) { $el.prop('disabled', false).prop('readonly', false); if ($el.hasClass('hasDatepicker') && typeof $el.datepicker === 'function') { try { $el.datepicker('setDate', '${safeValue}'); } catch(e){} } $el.val('${safeValue}'); ${isValueChanged ? "$el.trigger('change');" : ""} } } catch(e) {}`);
            if (isValueChanged) el.dispatchEvent(new Event('change', { bubbles: true }));
            await ui.wait(100);
        },
        setBatchDateTime: async function (dateSelector, dateValue, timeSelector, timeValue) {
