            timeEl.value = timeValue;
            const safeDateSel = dateSelector.replace(/'/g, "\\'");
            const safeTimeSel = timeSelector.replace(/'/g, "\\'");
            const safeDateVal = dateValue.replace(/'/g, "\\'");
            const safeTimeVal = timeValue.replace(/'/g, "\\'");
            runInPageContext(`try { var $ = window.jQuery; if (!$) return; var $d = $('${safeDateSel}'); var $t = $('${safeTimeSel}'); if ($d.length) { $d.prop('disabled', false).prop('readonly', false); if ($d.hasClass('hasDatepicker') && typeof $d.datepicker === 'function') { try { $d.datepicker('setDate', '${safeDateVal}'); } catch(e){} } $d.val('${safeDateVal}'); } if ($t.length) { $t.prop('disabled', false).prop('readonly', false); $t.val('${safeTimeVal}'); } if ($d.length) $d.trigger('change'); } catch(e) {}`);
            dateEl.dispatchEvent(new Event('change', { bubbles: true }));
            await ui.wait(150);
        },
        waitForVisible: (selector, timeout = 10000) => {
            return new Promise((resolve, reject) => {
                const start = Date.now();
                const timer = setInterval(() => {
                    if (isStopRequested) {
                        clearInterval(timer);
                        return reject(new Error("NGƯỜI DÙNG BẤM DỪNG TIẾN TRÌNH"));
                    }
                    const el = document.querySelector(selector);
                    if (el && (el.offsetWidth > 0 || el.offsetHeight > 0 || el.offsetParent !== null)) {
                        clearInterval(timer); resolve(el);
                    } else if (Date.now() - start > timeout) {
                        clearInterval(timer); reject(`Timeout: Không tìm thấy ${selector}`);
                    }
                }, 100);
            });
        },
        waitForSuccessPopup: async function (timeout = 12000) {
            const start = Date.now();
            while (Date.now() - start < timeout) {
                checkInterrupt();
                const popup = document.querySelector('#popup_container');
                const btnOk = document.querySelector('#popup_ok');
                if (popup && btnOk && (popup.offsetWidth > 0 || popup.offsetParent !== null) && (btnOk.offsetWidth > 0 || btnOk.offsetParent !== null)) {
                    btnOk.click(); await ui.wait(400); return true;
                }
                await ui.wait(150);
            }
            return false;
        },
        clearPopups: async function () {
            let retry = 0;
            while (retry < 5) {
                const btnOk = document.querySelector('#popup_ok');
                if (btnOk && (btnOk.offsetWidth > 0 || btnOk.offsetHeight > 0 || btnOk.offsetParent !== null)) {
                    btnOk.click();
                    await new Promise(r => setTimeout(r, 400));
                    retry++;
                } else break;
            }
        },
        forceCloseModals: async function () {
            const btnLuuCLS = document.querySelector('#luu_cdcls');
            if (btnLuuCLS) {
                const dialogContainer = btnLuuCLS.closest('.ui-dialog');
                if (dialogContainer) {
                    const closeBtn = dialogContainer.querySelector('.ui-dialog-titlebar-close');
                    if (closeBtn) closeBtn.click();
