            }
            runInPageContext(`try { if (window.jQuery && window.jQuery.fn.dialog) { window.jQuery('.ui-dialog-content').each(function() { if (window.jQuery(this).dialog('isOpen')) { window.jQuery(this).dialog('close'); } }); } if (window.jQuery && window.jQuery.fn.modal) { window.jQuery('.modal.in, .modal.show').modal('hide'); } } catch(e) {}`);
            await new Promise(r => setTimeout(r, 250));
            await ui.clearPopups();
        }
    };

    async function safeSelectPackage(goiId, updateStatusFn = null) {
        checkInterrupt();
        if (updateStatusFn) updateStatusFn("Đang mở chọn gói xét nghiệm...");
        await new Promise((resolve, reject) => {
            let retries = 0;
            const checkTimer = setInterval(() => {
                if (isStopRequested) { clearInterval(checkTimer); return reject(new Error("NGƯỜI DÙNG BẤM DỪNG TIẾN TRÌNH")); }
                const selectGoi = document.querySelector('#goi_chi_dinh');
                if ((selectGoi && selectGoi.options.length > 1) || ++retries > 30) {
                    clearInterval(checkTimer); resolve();
                }
            }, 100);
        });

        const safeGoiId = goiId.replace(/'/g, "\\'");
        runInPageContext(`
            (function() {
                var $ = window.jQuery; if (!$) return; var goiId = '${safeGoiId}';
                window.tdhPackageCache = window.tdhPackageCache || {};
                document.body.setAttribute('data-tdh-cache-loaded', 'false');
                if (window.tdhPackageCache[goiId] && window.tdhPackageCache[goiId].length > 0) {
                    $('#goi_chi_dinh').val(goiId);
                    var $grid = $("#list_dv_chon");
                    $grid.jqGrid('clearGridData'); $grid.jqGrid('setGridParam', { data: window.tdhPackageCache[goiId] }).trigger('reloadGrid');
                    document.body.setAttribute('data-tdh-cache-loaded', 'true');
                } else {
                    if (!window.tdhCacheListenerAttached) {
                        window.tdhCacheListenerAttached = true;
                        $(document).ajaxSuccess(function(event, xhr, settings) {
                            if (settings.url && settings.url.indexOf('get_chi_dinh') !== -1 && settings.url.indexOf('id=') !== -1) {
                                try {
                                    var data = JSON.parse(xhr.responseText);
                                    var items = Array.isArray(data) ? data : (data.rows || data.data || []);
                                    if (items.length > 0) {
                                        var pId = new URLSearchParams(settings.url.split('?')[1]).get('id');
                                        if (pId) window.tdhPackageCache[pId] = items;
                                    }
                                } catch(e) {}
                            }
                        });
                    }
                }
            })();
        `);

        await ui.wait(150);
        if (document.body.getAttribute('data-tdh-cache-loaded') === 'true') {
            if (updateStatusFn) updateStatusFn("⚡ Nạp dữ liệu xét nghiệm (từ Cache)!");
            await ui.wait(300); return;
        }

        function triggerSelectPackage(val) {
            const safeVal = String(val).replace(/'/g, "\\'");
            runInPageContext(`(function() { var $ = window.jQuery; if (!$) return; $.ajaxPrefilter(function(options, originalOptions, jqXHR) { if (options.url && options.url.indexOf('get_chi_dinh') !== -1) options.cache = false; }); var $goi = $('#goi_chi_dinh'); if ($goi.length) $goi.val('${safeVal}').trigger('change'); })();`);
        }

        const MAX_ATTEMPTS = 5;
        let isLoaded = false;
        for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
            checkInterrupt();
            if (updateStatusFn) updateStatusFn(`Đang nạp danh sách dịch vụ (Lần ${attempt})`);
            triggerSelectPackage(safeGoiId);
            isLoaded = await (async () => {
                return new Promise((resolve, reject) => {
                    let retries = 0;
                    const gridTimer = setInterval(() => {
                        if (isStopRequested) { clearInterval(gridTimer); return reject(new Error("NGƯỜI DÙNG BẤM DỪNG TIẾN TRÌNH")); }
                        if (document.querySelectorAll('#list_dv_chon tr.jqgrow, #gview_list_dv_chon tr.jqgrow').length > 0) {
                            clearInterval(gridTimer); resolve(true);
                        } else if (++retries >= 35) {
                            clearInterval(gridTimer); resolve(false);
                        }
                    }, 100);
                });
            })();
            if (isLoaded) {
                runInPageContext(`(function() { var $ = window.jQuery; var $grid = $("#list_dv_chon"); if ($ && $grid.length) { var data = $grid.jqGrid('getRowData'); if (data && data.length > 0) { window.tdhPackageCache = window.tdhPackageCache || {}; window.tdhPackageCache['${safeGoiId}'] = data; } } })();`);
                break;
            }
            runInPageContext(`(function() { var $ = window.jQuery; var $grid = $("#list_dv_chon"); if ($ && $grid.length && $grid.find('tr.jqgrow').length === 0) { var bustUrl = 'get_chi_dinh?id=' + encodeURIComponent('${safeGoiId}') + '&_t=' + Date.now(); $.getJSON(bustUrl, function(data) { if (data && (Array.isArray(data) || typeof data === 'object')) { var items = Array.isArray(data) ? data : (data.rows || data.data || []); if (items.length > 0) { window.tdhPackageCache = window.tdhPackageCache || {}; window.tdhPackageCache['${safeGoiId}'] = items; $grid.jqGrid('clearGridData'); $grid.jqGrid('setGridParam', { data: items }).trigger('reloadGrid'); } } }); } })();`);
            await ui.wait(400);
            if (document.querySelectorAll('#list_dv_chon tr.jqgrow, #gview_list_dv_chon tr.jqgrow').length > 0) { isLoaded = true; break; }
            if (attempt < MAX_ATTEMPTS) { triggerSelectPackage("0"); await ui.wait(350); }
        }
        await ui.wait(300); await ui.clearPopups();
    }

