        targetContainer.appendChild(modalDiv);

        const rowsContainer = document.getElementById('tdh-rows-container');
        const btnAdd = document.getElementById('tdh-btn-add');
        const btnRun = document.getElementById('tdh-btn-run');
        const btnStop = document.getElementById('tdh-btn-stop');
        const statusEl = document.getElementById('tdh-status');
        const btnClose = document.getElementById('tdh-btn-close');
        const btnLoadGoi = document.getElementById('tdh-btn-load-goi');
        const rowCounter = document.getElementById('tdh-row-counter');
        const mainBody = document.getElementById('tdh-main-body');

        const btnLoadDb = document.getElementById('tdh-btn-load-db');
        const selDienBien = document.getElementById('tdh-sel-maudienbien');
        const textDienBien = document.getElementById('tdh-text-dienbien');
        const chkXN = document.getElementById('tdh-chk-xn');
        const chkDB = document.getElementById('tdh-chk-db');

        const btnLoadYl = document.getElementById('tdh-btn-load-yl');
        const selYLenh = document.getElementById('tdh-sel-mauylenh');
        const textYLenh = document.getElementById('tdh-text-ylenh');

        let isUserOpened = false;

        function updateRowCounter() {
            const count = document.querySelectorAll('.tdh-time-row').length;
            if (rowCounter) rowCounter.textContent = `${count}/${MAX_TASKS_LIMIT}`;
            if (count >= MAX_TASKS_LIMIT) {
                btnAdd.disabled = true; btnAdd.style.opacity = '0.5'; btnAdd.style.cursor = 'not-allowed';
            } else {
                btnAdd.disabled = false; btnAdd.style.opacity = '1'; btnAdd.style.cursor = 'pointer';
            }
        }

        const openModalFull = () => {
            isUserOpened = true;
            dockDiv.style.display = 'none';
            modalDiv.style.top = '5vh';
            modalDiv.style.left = '50%';
            modalDiv.style.transform = 'translateX(-50%)';
            modalDiv.style.right = 'auto';
            modalDiv.style.bottom = 'auto';
            modalDiv.style.display = 'flex';
        };

        const closeLogic = () => {
            isUserOpened = false;
            modalDiv.style.display = 'none';
            if (isDockEnabled && hasCostReloadTarget() && checkUserBelongsToDoctorList()) {
                dockDiv.style.display = 'flex';
            } else {
                dockDiv.style.display = 'none';
            }
        };

        btnClose.onclick = closeLogic;
        dockDiv.onclick = openModalFull;

        // LẮNG NGHE PHÍM TẮT: OPTION (MAC) / ALT (WIN) + SHIFT + L ĐỂ BẬT/TẮT DOCK
        window.addEventListener('keydown', (e) => {
            if (e.altKey && e.shiftKey && (e.key === 'L' || e.key === 'l' || e.code === 'KeyL')) {
                const activeTag = document.activeElement ? document.activeElement.tagName.toLowerCase() : '';
                const isTyping = ['input', 'textarea', 'select'].includes(activeTag) || (document.activeElement && document.activeElement.isContentEditable);
                if (isTyping) return;

                e.preventDefault();
                e.stopPropagation();

                isDockEnabled = !isDockEnabled;
                if (!isDockEnabled) {
                    isUserOpened = false;
                    modalDiv.style.display = 'none';
                    dockDiv.style.display = 'none';
                }
            }
        }, true);

        const header = document.getElementById('tdh-header');
        let isDragging = false, startX, startY, initLeft, initTop;

        header.onmousedown = (e) => {
            if (e.target.closest('#tdh-btn-close')) return;
            isDragging = true; startX = e.clientX; startY = e.clientY;
            const rect = modalDiv.getBoundingClientRect(); initLeft = rect.left; initTop = rect.top;
            modalDiv.style.transform = 'none'; modalDiv.style.left = initLeft + 'px'; modalDiv.style.top = initTop + 'px';
            modalDiv.style.right = 'auto';

            const onMouseMove = (ev) => {
                if (!isDragging) return;
                const maxLeft = Math.max(0, window.innerWidth - modalDiv.offsetWidth);
                const maxTop = Math.max(0, window.innerHeight - modalDiv.offsetHeight);
                modalDiv.style.left = Math.max(0, Math.min(initLeft + (ev.clientX - startX), maxLeft)) + 'px';
                modalDiv.style.top = Math.max(0, Math.min(initTop + (ev.clientY - startY), maxTop)) + 'px';
            };
            const onMouseUp = () => { isDragging = false; window.removeEventListener('mousemove', onMouseMove); window.removeEventListener('mouseup', onMouseUp); };
            window.addEventListener('mousemove', onMouseMove); window.addEventListener('mouseup', onMouseUp);
        };

        function syncSelectOptions(sourceSelector, targetSelector, preferredValue = null) {
            const src = document.querySelector(sourceSelector);
            const tgt = document.querySelector(targetSelector);
            if (!src || !tgt || !src.options || src.options.length === 0) return false;
            tgt.innerHTML = '';
            for (let i = 0; i < src.options.length; i++) {
                const opt = src.options[i];
                const newOpt = document.createElement('option');
                newOpt.value = opt.value; newOpt.textContent = opt.textContent; tgt.appendChild(newOpt);
            }
            if (preferredValue !== null && [...tgt.options].some(o => o.value === preferredValue)) tgt.value = preferredValue;
            else tgt.value = src.value;
            return true;
        }

        function syncGoiOptions() { return syncSelectOptions('#goi_chi_dinh', '#tdh-sel-goi'); }
        function syncDienBienOptions() { return syncSelectOptions('#maudienbien', '#tdh-sel-maudienbien', "0"); }
        function syncYLenhOptions() { return syncSelectOptions('#sel_ylenhkhac_mau', '#tdh-sel-mauylenh', "0"); }

        btnLoadGoi.onclick = async () => {
            statusEl.textContent = '🔄 Đang mở modal HIS để quét gói...';
            stealthMode.enable();
            try {
                const btnChiDinh = document.querySelector('#chi_dinh_dv');
                if (btnChiDinh && btnChiDinh.offsetParent !== null) {
                    btnChiDinh.click(); await ui.wait(800); syncGoiOptions(); await ui.forceCloseModals();
                } else syncGoiOptions();
                statusEl.textContent = '✅ Đã cập nhật xong danh sách gói xét nghiệm!';
            } finally { stealthMode.disable(); }
        };

        btnLoadDb.onclick = () => { syncDienBienOptions(); statusEl.textContent = '✅ Đã nạp lại danh sách mẫu diễn biến!'; };
        btnLoadYl.onclick = () => { syncYLenhOptions(); statusEl.textContent = '✅ Đã nạp lại danh sách mẫu y lệnh!'; };

        selDienBien.onchange = async () => {
            const val = selDienBien.value;
            if (val === "0" || !val) { textDienBien.value = ""; return; }
            statusEl.textContent = '🔄 Đang nạp nội dung mẫu diễn biến...';
            await ui.setSelectValue('#maudienbien', val);
            await ui.wait(800); 
            const hisDienBien = document.querySelector('#dienbienbenh');
            if (hisDienBien) textDienBien.value = hisDienBien.value;
            statusEl.textContent = '✅ Đã nạp nội dung diễn biến thành công!';
        };

        selYLenh.onchange = async () => {
            const val = selYLenh.value;
            if (val === "0" || !val) { textYLenh.value = ""; return; }
            statusEl.textContent = '🔄 Đang nạp nội dung mẫu y lệnh...';
            await ui.setSelectValue('#sel_ylenhkhac_mau', val);
            await ui.wait(800); 
            const hisYLenh = document.querySelector('#ylenh');
            if (hisYLenh) textYLenh.value = hisYLenh.value;
            statusEl.textContent = '✅ Đã nạp nội dung y lệnh thành công!';
        };

        async function initDepartmentDefaults() {
            const hasKhoaBS = syncSelectOptions('#khoabs', '#tdh-sel-khoabs', DEFAULT_KHOA_ID);
            const hasKhoaDD = syncSelectOptions('#khoayta', '#tdh-sel-khoayta', DEFAULT_KHOA_ID);

            if (hasKhoaBS || hasKhoaDD) {
                await ui.setSelectValue('#khoabs', DEFAULT_KHOA_ID);
                await ui.setSelectValue('#khoayta', DEFAULT_KHOA_ID);
                await ui.wait(800);
                syncSelectOptions('#cbbacsidieutri', '#tdh-sel-cbbacsidieutri');
                syncSelectOptions('#cb_yta', '#tdh-sel-cb_yta');
                syncGoiOptions(); 
                syncDienBienOptions();
                syncYLenhOptions();
                return true;
            }
            return false;
        }

        let retryInit = 0;
        const autoSyncTimer = setInterval(async () => {
            if (await initDepartmentDefaults() || retryInit > 10) clearInterval(autoSyncTimer);
            retryInit++;
        }, 1000);

        function setupSelectSync(targetId, sourceSelector, isDepartment = false, relatedChildSync = null) {
            const tgt = document.getElementById(targetId);
            if (!tgt) return;
            tgt.onchange = async () => {
                await ui.setSelectValue(sourceSelector, tgt.value);
                if (isDepartment && relatedChildSync) { await ui.wait(800); relatedChildSync(); }
            };
        }

        setupSelectSync('tdh-sel-khoabs', '#khoabs', true, () => syncSelectOptions('#cbbacsidieutri', '#tdh-sel-cbbacsidieutri'));
        setupSelectSync('tdh-sel-cbbacsidieutri', '#cbbacsidieutri');
        setupSelectSync('tdh-sel-khoayta', '#khoayta', true, () => syncSelectOptions('#cb_yta', '#tdh-sel-cb_yta'));
        setupSelectSync('tdh-sel-cb_yta', '#cb_yta');

        // Hàm thêm dòng sử dụng 1 ô datetime-local - CHỈ LẮNG NGHE SỰ KIỆN BLUR
        function addRow(dtValue = defaultDateTimeStr) {
            const currentRows = document.querySelectorAll('.tdh-time-row');
            if (currentRows.length >= MAX_TASKS_LIMIT) {
                alert(`Chỉ được phép thực hiện tối đa ${MAX_TASKS_LIMIT} tác vụ trong 1 lần chạy.`);
                return;
            }
            const row = document.createElement('div');
            row.className = 'tdh-time-row';
            row.style.cssText = 'display: flex; gap: 8px; align-items: center; margin-bottom: 8px;';
            row.innerHTML = `
                <input type="datetime-local" class="tdh-input-datetime tdh-input-style" value="${dtValue}" min="${minIsoDateTime}" max="${maxIsoDateTime}" title="Bấm 1 lần để chọn cả Ngày và Giờ (+- 3 ngày)" style="text-align: center; width: 195px; cursor: pointer; font-weight: 500;" />
                <button class="tdh-btn-remove" title="Xóa dòng" style="background: transparent; border: none; color: #ef4444; cursor: pointer; padding: 4px; border-radius: 6px; display: flex; align-items: center; justify-content: center; transition: background 0.2s;" onmouseover="this.style.background='#fee2e2'" onmouseout="this.style.background='transparent'">
                    <svg width="20" height="20" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
                </button>
                <div class="tdh-status-icon" style="width: 24px; text-align: center; font-size: 14px; font-weight: bold;"></div>
            `;

            const inputDt = row.querySelector('.tdh-input-datetime');

            // CHỈ KIỂM TRA DUY NHẤT KHI CHUYỂN FOCUS RỜI KHỎI Ô (BLUR)
            inputDt.addEventListener('blur', () => {
                dateTimeFormatter.validateAndFallbackInput(inputDt);
            });

            row.querySelector('.tdh-btn-remove').onclick = () => {
                if (document.querySelectorAll('.tdh-time-row').length > 1) { 
                    row.remove(); 
                    updateRowCounter(); 
                } else alert("Cần giữ lại ít nhất 1 dòng cấu hình.");
            };
            rowsContainer.appendChild(row);
            updateRowCounter();
        }

        addRow();

        btnAdd.onclick = () => {
            const allRows = document.querySelectorAll('.tdh-time-row');
            if (allRows.length >= MAX_TASKS_LIMIT) {
                alert(`Chỉ được phép thực hiện tối đa ${MAX_TASKS_LIMIT} tác vụ.`); return;
            }
            let nextVal = defaultDateTimeStr;
            if (allRows.length > 0) {
                const lastVal = allRows[allRows.length - 1].querySelector('.tdh-input-datetime').value;
                if (lastVal) {
                    const datePart = lastVal.split('T')[0];
                    nextVal = `${datePart}T10:00`;
                }
            }
            addRow(nextVal);
        };

        btnStop.onclick = () => {
            if (btnRun.dataset.running !== 'true') return;
            isStopRequested = true;
            statusEl.textContent = '🛑 Đang yêu cầu dừng ngay lập tức... Vui lòng đợi...';
            statusEl.style.color = '#dc2626';
            btnStop.disabled = true;
            btnStop.style.opacity = '0.5';
        };

        btnRun.onclick = async () => {
            if (btnRun.dataset.running === 'true') return;

            const isXN = chkXN.checked, isDB = chkDB.checked;
            const dienbienText = textDienBien?.value.trim() || "";
            const ylenhText = textYLenh?.value.trim() || "";

            if (!isXN && !isDB) { alert("Vui lòng chọn xét nghiệm hoặc ghi diễn biến cho tờ điều trị!"); return; }
            if (!isXN && isDB && !dienbienText) { alert("Tờ điều trị chưa có diễn biến!"); return; }

            const selGoiEl = document.getElementById('tdh-sel-goi');
            const goiId = selGoiEl?.value;
            const goiText = selGoiEl?.options[selGoiEl.selectedIndex]?.textContent?.trim() || 'N/A';

            if (isXN && !goiId) { alert("Vui lòng chọn một Gói xét nghiệm hoặc bấm 'Đọc gói'!"); return; }

            const selBsEl = document.getElementById('tdh-sel-cbbacsidieutri');
            if (!selBsEl?.value) { alert("Vui lòng chọn Bác sĩ điều trị trước khi chạy!"); return; }

            const rows = document.querySelectorAll('.tdh-time-row');
            if (rows.length === 0) return;
            if (rows.length > MAX_TASKS_LIMIT) { alert(`Số lượng tác vụ vượt quá mức cho phép (${MAX_TASKS_LIMIT}). Vui lòng xóa bớt.`); return; }

            // Kiểm tra validation lần cuối cho tất cả các dòng trước khi bắt đầu thực thi
            for (let r of rows) {
                const inputEl = r.querySelector('.tdh-input-datetime');
                dateTimeFormatter.validateAndFallbackInput(inputEl);
            }

            const startEpoch = Date.now(), startISO = new Date(startEpoch).toISOString();
            const loggedMauUser = getCurrentLoggedMauUser();
            const finalMauUser = loggedMauUser || selBsEl?.options[selBsEl.selectedIndex]?.textContent?.trim() || 'N/A';

            // Kích hoạt trạng thái đang chạy
            isStopRequested = false;
            btnRun.dataset.running = 'true';
            btnRun.style.display = 'none';
            btnStop.style.display = 'inline-flex';
            btnStop.disabled = false;
            btnStop.style.opacity = '1';

            mainBody.classList.add('tdh-locked-form');
            screenShield.enable();
            stealthMode.enable();

            renderDockContent(true, 0, rows.length);
            statusEl.textContent = '🚀 Bắt đầu tiến trình tự động ngầm...';
            statusEl.style.color = '#2563eb';

            let successCount = 0; 
            const cancelledDetails = [];

            try {
                for (let i = 0; i < rows.length; i++) {
                    checkInterrupt();
                    renderDockContent(true, i + 1, rows.length);

                    const row = rows[i];
                    const inputDt = row.querySelector('.tdh-input-datetime');

                    // Phân rã chuỗi datetime-local thành ngày DD/MM/YYYY và giờ HH:mm:ss
                    const dtParsed = dateTimeFormatter.parseDateTimeLocal(inputDt.value.trim());
                    const dateVal = dtParsed.dateStr;
                    const timeVal = dtParsed.timeStr;

                    const iconContainer = row.querySelector('.tdh-status-icon');
                    iconContainer.innerHTML = '⏳';
                    const updateSubStatus = (stepText) => { statusEl.textContent = `[${i + 1}/${rows.length}] ${stepText}`; };

                    try {
                        await taoChiDinhCLS(dateVal, timeVal, goiId, dienbienText, ylenhText, updateSubStatus, i === 0, isXN, isDB);
                        iconContainer.innerHTML = '<span style="color: #16a34a;" title="Hoàn tất">✅</span>';
                        successCount++;
                    } catch (err) {
                        if (isStopRequested || String(err.message || "").includes("NGƯỜI DÙNG BẤM DỪNG")) {
                            iconContainer.innerHTML = '<span style="color: #dc2626;" title="Đã hủy bỏ">🛑</span>';
                            cancelledDetails.push(`Dòng ${i + 1} (${dateVal} ${timeVal}): Đã bị dừng thủ công`);
                            throw err;
                        }
                        console.error("Lỗi tại dòng:", i + 1, err);
                        iconContainer.innerHTML = '<span style="color: #ef4444;" title="Lỗi thực thi">❌</span>';
                        statusEl.textContent = `❌ Lỗi tại dòng ${i + 1}! Đang chuyển dòng tiếp...`;
                        statusEl.style.color = '#ef4444';
                        cancelledDetails.push(`Dòng ${i + 1} (${dateVal} ${timeVal}): ${String(err.message || err).slice(0, 80)}`);
                    }
                    await ui.wait(600);
                }

                const elapsedSeconds = Math.round((Date.now() - startEpoch) / 1000);
                statusEl.textContent = `🎉 Hoàn tất ${successCount}/${rows.length} tác vụ trong ${elapsedSeconds}s!`;
                statusEl.style.color = '#16a34a';

                firebaseLogger.pushLog({
                    timestamp: startISO, mauUser: finalMauUser, packageName: isXN ? goiText : "KHÔNG CHỈ ĐỊNH",
                    totalTasks: rows.length, successTasks: successCount, duration: `${elapsedSeconds}s`,
                    cancelledInfo: cancelledDetails.length > 0 ? cancelledDetails.join('; ') : 'none', createdAt: startEpoch
                });

            } catch (globalErr) {
                if (isStopRequested || String(globalErr.message || "").includes("NGƯỜI DÙNG BẤM DỪNG")) {
                    const elapsedSeconds = Math.round((Date.now() - startEpoch) / 1000);
                    statusEl.textContent = `🛑 Đã dừng tiến trình! Đã thực hiện ${successCount}/${rows.length} tác vụ.`;
                    statusEl.style.color = '#dc2626';
                    await ui.forceCloseModals();

                    firebaseLogger.pushLog({
                        timestamp: startISO, mauUser: finalMauUser, packageName: isXN ? goiText : "KHÔNG CHỈ ĐỊNH",
                        totalTasks: rows.length, successTasks: successCount, duration: `${elapsedSeconds}s`,
                        cancelledInfo: `DỪNG BỞI NGƯỜI DÙNG: ${cancelledDetails.join('; ')}`, createdAt: startEpoch
                    });
                } else {
                    console.error("Lỗi toàn cục:", globalErr);
                    statusEl.textContent = `❌ Có lỗi ngắt quãng: ${String(globalErr.message || globalErr).slice(0, 50)}`;
                    statusEl.style.color = '#ef4444';
                }
            } finally {
                stealthMode.disable();
                screenShield.disable();
                mainBody.classList.remove('tdh-locked-form');

                btnRun.dataset.running = 'false';
                btnRun.style.display = 'flex';
                btnStop.style.display = 'none';

                renderDockContent(false);
                updateRowCounter();

                // TỰ ĐỘNG THU GỌN DOCK & MỞ LẠI MODAL NẾU ĐÃ BỊ ĐÓNG KHI ĐANG CHẠY NGẦM
                if (!isUserOpened) {
                    openModalFull();
                }
            }
        };

        // VÒNG LẶP KIỂM TRA HIỂN THỊ: CHỈ HIỂN THỊ DOCK KHI ĐÃ BẬT BẰNG PHÍM TẮT VÀ ĐỦ ĐIỀU KIỆN
        setInterval(() => {
            const isTargetVisible = hasCostReloadTarget(), isDoctorValid = checkUserBelongsToDoctorList();
            if (isDockEnabled && isTargetVisible && isDoctorValid) {
                if (isUserOpened) { 
                    modalDiv.style.display = 'flex'; 
                    dockDiv.style.display = 'none'; 
                } else { 
                    modalDiv.style.display = 'none'; 
                    dockDiv.style.display = 'flex'; 
                }
            } else { 
                modalDiv.style.display = 'none'; 
                dockDiv.style.display = 'none'; 
            }
        }, 500);
    }

    let checkCount = 0;
    const mainTimer = setInterval(async () => {
        const selKhoaBS = document.querySelector('#khoabs');
        if (selKhoaBS && selKhoaBS.value !== DEFAULT_KHOA_ID) await ui.setSelectValue('#khoabs', DEFAULT_KHOA_ID);

        const loggedUser = getCurrentLoggedMauUser();
        if (loggedUser) {
            const normalizedUser = loggedUser.toLowerCase();
            const isPhanDinhHuy = normalizedUser.includes("phan đình huy") || 
                                  normalizedUser.includes("phan dinh huy") || 
                                  normalizedUser.includes("1345163") ||
                                  normalizedUser.includes("phandinhhuy");

            if (isPhanDinhHuy) {
                initUI();
            } else {
                console.log("[Lab Automator] Kịch bản bị vô hiệu hóa vì tài khoản không thuộc phân quyền cấp phép.");
            }
            clearInterval(mainTimer);
        }
        if (++checkCount > 50) clearInterval(mainTimer);
    }, 600);

})();
